/* ==========================================================================
   IMPORTACIÓN Y EXPORTACIÓN DE LIBRO DE EXCEL (10 REGIONES: I A X)
   ========================================================================== */
function normalizeRegionIdValue(rawVal, fallbackId) {
  const clean = String(rawVal || '').trim().toUpperCase();
  if (!clean) return fallbackId;
  const arabicToRoman = { '1': 'I', '2': 'II', '3': 'III', '4': 'IV', '5': 'V', '6': 'VI', '7': 'VII', '8': 'VIII', '9': 'IX', '10': 'X' };
  if (arabicToRoman[clean]) return arabicToRoman[clean];
  for (const [num, rom] of Object.entries(arabicToRoman)) {
    if (clean === `REGION ${num}` || clean === `REGIÓN ${num}` || clean === `REG-${num}` || clean === `REG ${num}`) {
      return rom;
    }
  }
  for (const reg of REGIONS_CATALOG) {
    if (
      reg.id.toUpperCase() === clean ||
      `REG-${reg.id}` === clean ||
      `REGION ${reg.id}` === clean ||
      `REGIÓN ${reg.id}` === clean ||
      reg.name.toUpperCase() === clean ||
      clean.startsWith(`${reg.id}-`)
    ) {
      return reg.id;
    }
  }
  return clean;
}

function findRegionAndSubregionBySheetName(sheetName) {
  const clean = String(sheetName).trim().toUpperCase();
  const arabicToRoman = { '1': 'I', '2': 'II', '3': 'III', '4': 'IV', '5': 'V', '6': 'VI', '7': 'VII', '8': 'VIII', '9': 'IX', '10': 'X' };
  for (const [num, rom] of Object.entries(arabicToRoman)) {
    if (clean === num || clean === `REGION ${num}` || clean === `REGIÓN ${num}` || clean === `REG-${num}` || clean === `REG ${num}`) {
      return { regionId: rom, subregionId: `REG-${rom}` };
    }
  }

  // 1. Coincidencia exacta por ID de Región ('I'..'X', 'REG-I'..'REG-X', o prefijo 'V-1' -> 'V')
  for (const reg of REGIONS_CATALOG) {
    if (
      reg.id.toUpperCase() === clean ||
      `REG-${reg.id}` === clean ||
      `REGION ${reg.id}` === clean ||
      `REGIÓN ${reg.id}` === clean ||
      reg.name.toUpperCase() === clean ||
      clean.startsWith(`${reg.id}-`)
    ) {
      return { regionId: reg.id, subregionId: `REG-${reg.id}` };
    }
  }

  // 2. Coincidencia por nombre descriptivo de la Región
  if (clean.length >= 4) {
    for (const reg of REGIONS_CATALOG) {
      if (reg.name.toUpperCase().includes(clean)) {
        return { regionId: reg.id, subregionId: `REG-${reg.id}` };
      }
    }
  }

  return { regionId: 'I', subregionId: 'REG-I' };
}

function getRowFieldNormalized(rowObj, candidateKeys) {
  if (!rowObj || typeof rowObj !== 'object') return '';
  const normalizeKey = k =>
    String(k || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-zA-Z0-9]/g, '')
      .toLowerCase();

  const normalizedMap = {};
  for (const [k, v] of Object.entries(rowObj)) {
    normalizedMap[normalizeKey(k)] = v;
  }

  for (const candidate of candidateKeys) {
    if (typeof rowObj[candidate] !== 'undefined' && rowObj[candidate] !== null && String(rowObj[candidate]).trim() !== '') {
      return rowObj[candidate];
    }
    const nk = normalizeKey(candidate);
    if (typeof normalizedMap[nk] !== 'undefined' && normalizedMap[nk] !== null && String(normalizedMap[nk]).trim() !== '') {
      return normalizedMap[nk];
    }
  }
  return '';
}

function handleImportExcelFile(event) {
  const file = event.target.files?.[0];
  if (!file) return;

  let targetMod = document.getElementById('adminExcelModuleFilter')?.value || 'MOD1';

  const reader = new FileReader();
  reader.onload = e => {
    try {
      const data = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: 'array' });

      // Autodetectar si el archivo Excel corresponde a Módulo 1 o Módulo 2 según sus encabezados
      for (const sName of workbook.SheetNames) {
        const testRows = XLSX.utils.sheet_to_json(workbook.Sheets[sName], { defval: '' });
        if (testRows.length > 0) {
          const sample = testRows[0];
          const hasCorrelativo = getRowFieldNormalized(sample, ['Correlativo licencia', 'Correlativo']) !== '';
          const hasResolucionOrArea =
            getRowFieldNormalized(sample, ['Resolución Licencia', 'Resolucion Licencia', 'Área (Ha)', 'Area (Ha)']) !== '' ||
            Object.keys(sample).some(k => k.toLowerCase().includes('poligono') || k.toLowerCase().includes('area') || k.toLowerCase().includes('área'));
          if (hasCorrelativo && !hasResolucionOrArea) {
            targetMod = 'MOD1';
          } else if (hasResolucionOrArea && !hasCorrelativo) {
            targetMod = 'MOD2';
          }
          const filterSelect = document.getElementById('adminExcelModuleFilter');
          if (filterSelect) filterSelect.value = targetMod;
          break;
        }
      }

      let importedRecords = [];

      workbook.SheetNames.forEach(sheetName => {
        const sheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(sheet, { defval: '' });
        const mappedLoc = findRegionAndSubregionBySheetName(sheetName);

        rows.forEach((r, idx) => {
          const rawReg = getRowFieldNormalized(r, ['Región', 'Region']);
          const rawNo = getRowFieldNormalized(r, ['No.', 'No']);
          const rawYear = getRowFieldNormalized(r, ['Año', 'Anio']);
          const rawCorr = getRowFieldNormalized(r, ['Correlativo licencia', 'Correlativo']);
          const rawRes = getRowFieldNormalized(r, ['Resolución Licencia', 'Resolución de Licencia', 'Resolucion']);
          const rawTit = getRowFieldNormalized(r, ['Titular']);

          // Ignorar filas completamente vacías al final de las hojas
          if (!rawReg && !rawNo && !rawCorr && !rawRes && !rawTit) {
            return;
          }

          const regionId = normalizeRegionIdValue(rawReg, mappedLoc.regionId);
          const subregionId = `REG-${regionId}`;

          if (targetMod === 'MOD1') {
            importedRecords.push({
              id: `M1-IMP-${Date.now()}-${sheetName}-${idx}`,
              regionId,
              subregionId,
              no: Number(rawNo || idx + 1),
              year: Number(rawYear || 2017),
              correlativo: String(rawCorr || (idx + 1)).trim(),
              emitida: String(getRowFieldNormalized(r, ['¿La licencia fue emitida?', 'Emitida']) || ''),
              subregion: String(getRowFieldNormalized(r, ['Subregión', 'Subregion']) || '').trim(),
              expediente: String(getRowFieldNormalized(r, ['Expediente']) || '').trim(),
              resolucion: String(rawRes || '').trim(),
              fechaAprobacion: String(getRowFieldNormalized(r, ['Fecha de aprobación', 'Fecha']) || '').trim(),
              titular: String(rawTit || '').trim(),
              representante: String(getRowFieldNormalized(r, ['Representante']) || '').trim(),
              tipoLicencia: String(getRowFieldNormalized(r, ['Tipo de Licencia', 'Tipo de licencia']) || '').trim(),
              departamento: String(getRowFieldNormalized(r, ['Departamento']) || '').trim(),
              municipio: String(getRowFieldNormalized(r, ['Municipio']) || '').trim(),
              areaObligacion: String(getRowFieldNormalized(r, ['Área de obligación', 'Area de obligacion']) || '').trim(),
              areaProduccion: String(getRowFieldNormalized(r, ['Área de producción', 'Area de produccion']) || '').trim(),
              volumen: String(getRowFieldNormalized(r, ['Volumen']) || '').trim(),
              tratamientoSilvicultural: String(getRowFieldNormalized(r, ['Tratamiento silvicultural']) || '').trim(),
              especies: String(getRowFieldNormalized(r, ['Especies']) || '').trim(),
              obs: String(getRowFieldNormalized(r, ['Observación', 'Observaciones']) || '').trim()
            });
          } else {
            const rawArea = getRowFieldNormalized(r, ['Área (Ha)', 'Area (Ha)', 'Área', 'Area']);
            importedRecords.push({
              id: `M2-IMP-${Date.now()}-${sheetName}-${idx}`,
              regionId,
              subregionId,
              no: Number(rawNo || idx + 1),
              subregion: String(getRowFieldNormalized(r, ['Subregión', 'Subregion']) || '').trim(),
              resolucion: String(rawRes || '').trim(),
              expediente: String(getRowFieldNormalized(r, ['Expediente']) || '').trim(),
              titular: String(rawTit || '').trim(),
              year: Number(rawYear || 2017),
              area: Number(rawArea || 0),
              disponibilidad: String(getRowFieldNormalized(r, ['Estado de disponibilidad del expediente físico', 'Disponibilidad']) || '').trim(),
              obs: String(getRowFieldNormalized(r, ['Observaciones', 'Observación']) || '').trim()
            });
          }
        });
      });

      if (!importedRecords.length) {
        showToast('⚠️ El libro de Excel no contiene filas válidas.');
        return;
      }

      if (targetMod === 'MOD1') {
        appState.mod1Licenses = importedRecords;
        appState.mod1ClearedByAdmin = false;
      } else {
        appState.mod2Licenses = importedRecords;
        appState.mod2ClearedByAdmin = false;
      }

      saveStateToStorage();
      renderAdminDashboard();
      if (currentSession.authenticated) {
        renderModule1Table();
        renderModule2Table();
      }
      event.target.value = '';
      showToast(`📥 Se importaron ${importedRecords.length} registros desde ${workbook.SheetNames.length} hoja(s) para ${targetMod === 'MOD1' ? 'Módulo 1' : 'Módulo 2'}.`);
    } catch (err) {
      console.error(err);
      event.target.value = '';
      showToast('❌ Error procesando el libro de Excel.');
    }
  };
  reader.readAsArrayBuffer(file);
}

function clearUploadedExcelModule() {
  const targetMod = document.getElementById('adminExcelModuleFilter')?.value || 'MOD1';
  const modLabel = targetMod === 'MOD1'
    ? 'Módulo 1 (Sin información digital)'
    : 'Módulo 2 (Sin polígono digital)';

  const previousCount = targetMod === 'MOD1' ? appState.mod1Licenses.length : appState.mod2Licenses.length;

  if (targetMod === 'MOD1') {
    appState.mod1Licenses = [];
    appState.mod1ClearedByAdmin = true;
  } else {
    appState.mod2Licenses = [];
    appState.mod2ClearedByAdmin = true;
  }

  const fileInput = document.getElementById('excelUploadInput');
  if (fileInput) fileInput.value = '';

  saveStateToStorage();
  renderAdminDashboard();
  if (currentSession.authenticated) {
    renderModule1Table();
    renderModule2Table();
  }
  showToast(`🗑️ Se eliminaron los ${previousCount} registros cargados en ${modLabel}. Ahora está en 0.`);
}

function exportConsolidatedExcel() {
  if (typeof XLSX === 'undefined') return;
  const targetMod = document.getElementById('adminExcelModuleFilter')?.value || 'MOD1';
  const wb = XLSX.utils.book_new();

  if (targetMod === 'MOD1') {
    const rows = appState.mod1Licenses.map(l => ({
      Región: l.regionId,
      'No.': l.no,
      Año: l.year,
      'Correlativo licencia': l.correlativo,
      '¿La licencia fue emitida?': l.emitida || 'PENDIENTE',
      Subregión: l.emitida === 'Sí' ? (l.subregion || '') : '',
      Expediente: l.emitida === 'Sí' ? (l.expediente || '') : '',
      'Resolución de Licencia': l.emitida === 'Sí' ? (l.resolucion || '') : '',
      'Fecha de aprobación': l.emitida === 'Sí' ? (l.fechaAprobacion || '') : '',
      Titular: l.emitida === 'Sí' ? (l.titular || '') : '',
      Representante: l.emitida === 'Sí' ? (l.representante || '') : '',
      'Tipo de Licencia': l.emitida === 'Sí' ? (l.tipoLicencia || '') : '',
      Departamento: l.emitida === 'Sí' ? (l.departamento || '') : '',
      Municipio: l.emitida === 'Sí' ? (l.municipio || '') : '',
      'Área de obligación': l.emitida === 'Sí' ? (l.areaObligacion || '') : '',
      'Área de producción': l.emitida === 'Sí' ? (l.areaProduccion || '') : '',
      Volumen: l.emitida === 'Sí' ? (l.volumen || '') : '',
      'Tratamiento silvicultural': l.emitida === 'Sí' ? (l.tratamientoSilvicultural || '') : '',
      Especies: l.emitida === 'Sí' ? (l.especies || '') : '',
      Observación: l.obs || ''
    }));
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows), 'Consolidado_Modulo_1');
    XLSX.writeFile(wb, `Consolidado_Modulo1_Sin_Info_Digital_${new Date().toISOString().slice(0, 10)}.xlsx`);
  } else {
    const rows = appState.mod2Licenses.map(l => ({
      Región: l.regionId,
      'No.': l.no,
      Subregión: l.subregion || '',
      'Resolución Licencia': l.resolucion,
      Expediente: l.expediente,
      Titular: l.titular,
      Año: l.year,
      'Área (Ha)': l.area,
      'Estado de disponibilidad del expediente físico': l.disponibilidad || 'PENDIENTE',
      Observaciones: l.obs || ''
    }));
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows), 'Consolidado_Modulo_2');
    XLSX.writeFile(wb, `Consolidado_Modulo2_Sin_Poligono_Digital_${new Date().toISOString().slice(0, 10)}.xlsx`);
  }

  showToast('📤 Consolidado Excel descargado correctamente.');
}

